@@ -14,6 +14,7 @@ defmodule Rian.Comptime do
   def fold({:call, {:id, "comptime"}, [e]}) do
     case eval(e) do
       {:ok, v} when is_integer(v) -> {:num, Integer.to_string(v)}
+      {:ok, v} when is_float(v) -> {:num, Float.to_string(v)}
       {:ok, true} -> {:id, "true"}
